"""Private cross-consumer experiment: native original-span feature preparation.

One bank prepares both directions per original span, preserving explicit seam
bindings. It does not yet deduplicate distinct spans sharing a feature curve.
Consumers retain all original source/port checks and verify the translated
curve and its preparation parameters before reusing a coefficient table.
"""
import bpy
from . import curved_feature_cache_nodes as cache
from . import curved_junction_nodes as boundary
from .curved_network_ownership_nodes import _compare

c=cache.c
IDENTITY=('Street ID','Span First','Span Last')
PREFIX='Prochitecture Streets / Shared native feature bank '


def _attribute(key):return '_st_fb_'+key.lower().replace(' ','_')


def parameters():
    original=cache.views.prepare(endpoint_tangents=True,interpolation=True,endpoint_frames=True)
    kinds={'NodeSocketFloat':'FLOAT','NodeSocketInt':'INT','NodeSocketBool':'BOOLEAN','NodeSocketVector':'FLOAT_VECTOR'}
    return [(s.name,kinds[s.socket_type]) for s in original.interface.items_tree
        if s.item_type=='SOCKET' and s.in_out=='INPUT'
        and s.name not in ('Geometry','Reverse','First Control','Last Control')]


def pack(g,call,valid,identity):
    table=call.outputs['Geometry']
    # These are live GN fields, not values resolved by the binding script.
    for key,kind in parameters():
        socket=call.inputs[key]
        assert len(socket.links)<=1
        value=socket.links[0].from_socket if socket.is_linked else socket.default_value
        table=c._store(g,table,_attribute(key),value,kind)
    for key,value in zip(IDENTITY,identity):table=c._store(g,table,_attribute(key),value,'INT')
    return c._store(g,table,'_st_fc_valid',c.named(g,'_st_fc_valid','BOOLEAN')*valid,'BOOLEAN')


def bound_view():
    name=PREFIX+'checked translated reader v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    original=cache.views.prepare(endpoint_tangents=True,interpolation=True,endpoint_frames=True)
    g=c.Graph(name);cache._copy_inputs(g,original)
    g.socket('Feature Curves','NodeSocketGeometry')
    for key in IDENTITY:g.socket(key,'NodeSocketInt')
    for socket in original.interface.items_tree:
        if socket.item_type=='SOCKET' and socket.in_out=='OUTPUT':g.socket(socket.name,socket.socket_type,'OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    match=1.
    for key in IDENTITY:match*=_compare(g,c.named(g,_attribute(key),'INT'),inp.outputs[key])
    table=c._select(g,inp.outputs['Feature Curves'],match)
    forward=c._select(g,table,_compare(g,c.named(g,'_st_fc_direction','INT'),0))
    size=c._count(g,inp.outputs['Geometry'])
    good=_compare(g,c._count(g,forward),size)*_compare(g,c._count(g,table),2.*size)
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    here=c._sample(g,inp.outputs['Geometry'],g.position(),0,'FLOAT_VECTOR')
    there=c._read(g,forward,'st_cc_p',0,'FLOAT_VECTOR')
    h=g.separate(here);t=g.separate(there)
    delta=g.xyz(h[0]-t[0],h[1]-t[1],0.)
    expected=c._sample(g,forward,c.named(g,'st_cc_p','FLOAT_VECTOR'),index,'FLOAT_VECTOR')
    actual=g.separate(g.position());sample=g.separate(expected);shift=g.separate(delta)
    same=1.
    for a,b,d in zip(actual,sample,shift):same*=g.math('LESS_THAN',g.math('ABSOLUTE',a-b-d),1e-4)
    good*=c._stat(g,inp.outputs['Geometry'],same)
    # Source frames may introduce float roundoff; they cannot change a binding,
    # a dimension or an enabled endpoint constraint by a material amount.
    for key,kind in parameters():
        stored=c._read(g,forward,_attribute(key),0,kind);wanted=inp.outputs[key]
        if kind in ('INT','BOOLEAN'):agrees=_compare(g,stored,wanted)
        elif kind=='FLOAT_VECTOR':
            agrees=1.
            for a,b in zip(g.separate(stored),g.separate(wanted)):
                agrees*=g.math('LESS_THAN',g.math('ABSOLUTE',a-b),1e-5)
            # Disabled tangent/axis values have no semantic effect.
            enabled=inp.outputs.get('Use '+key)
            if enabled is not None:agrees=c.choose(g,enabled,agrees,1.)
        else:agrees=g.math('LESS_THAN',g.math('ABSOLUTE',stored-c.V(g,wanted)),1e-6)
        good*=agrees
    for key,kind in [(k,'INT') for k in IDENTITY]+parameters():
        attr=g.node('GeometryNodeInputNamedAttribute');attr.data_type=kind
        attr.inputs['Name'].default_value=_attribute(key)
        good*=c._stat(g,table,attr.outputs['Exists'])
    table=c._store(g,table,'_st_fc_valid',c.named(g,'_st_fc_valid','BOOLEAN')*good,'BOOLEAN')
    for key in IDENTITY+tuple(k for k,_ in parameters()):
        remove=g.node('GeometryNodeRemoveAttribute');remove.inputs['Name'].default_value=_attribute(key)
        g.bind(table,remove.inputs['Geometry']);table=remove.outputs['Geometry']
    view=g.node('GeometryNodeGroup','Original coefficient-preserving view of a checked native feature')
    view.node_tree=cache.view();g.bind(table,view.inputs['Cache']);g.bind(delta,view.inputs['Translation'])
    for key in ('Reverse','First Control','Last Control'):g.bind(inp.outputs[key],view.inputs[key])
    for socket in out.inputs:
        if socket.name in view.outputs:g.bind(view.outputs[socket.name],socket)
    return g.g


def build(*,street_scoped=False):
    name=PREFIX+'original-span preparation v1'
    if street_scoped:name+=' / Owned Street v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for key in ('Sources','Mapping'):g.socket(key,'NodeSocketGeometry')
    if street_scoped:g.socket('Street ID','NodeSocketInt',default=-1)
    g.socket('Feature Curves','NodeSocketGeometry','OUTPUT');g.socket('Valid','NodeSocketBool','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    begin=g.node('GeometryNodeRepeatInput');end=g.node('GeometryNodeRepeatOutput')
    end.repeat_items.clear();end.repeat_items.new('GEOMETRY','Feature Curves');begin.pair_with_output(end)
    count=c._count(g,inp.outputs['Mapping'])
    valid=g.math('LESS_THAN',count,65537.)
    g.bind(c.choose(g,valid,count,0,'INT'),begin.inputs['Iterations'])
    from . import curved_port_nodes
    call=g.node('GeometryNodeGroup','Original source, feature and seam contract per authored span')
    call.node_tree=curved_port_nodes.build(interpolation=True,dimensions=True,emit_feature=True)
    g.bind(inp.outputs['Sources'],call.inputs['Sources']);g.bind(inp.outputs['Mapping'],call.inputs['Spans'])
    g.bind(begin.outputs['Iteration'],call.inputs['Index'])
    prepared=call.outputs['Feature Curves']
    if street_scoped:
        street=c._read(g,inp.outputs['Mapping'],'st_ps_street_id',begin.outputs['Iteration'],'INT')
        own=_compare(g,street,inp.outputs['Street ID'])
        # Preserve original row indices, including seam references. A lazy
        # geometry switch skips preparation for spans owned by other Streets.
        prepared=boundary._empty(g,prepared,own)
        valid*=_compare(g,inp.outputs['Street ID'],0,'GREATER_EQUAL')
    g.bind(boundary._join(g,begin.outputs['Feature Curves'],prepared),end.inputs['Feature Curves'])
    g.bind(end.outputs['Feature Curves'],out.inputs['Feature Curves']);g.bind(valid,out.inputs['Valid'])
    return g.g
